NS.Telemetry.prototype.snapshot=function(w,reason='AUTO',note=''){const s=snap28.call(this,w,reason,note);if(!s)return s;let wallet=0,market=0,trades=0,vol=0,gold=0,wages=0,cons=0,tax=0,pub=0,unemployed=0,capacity=0,used=0;for(const r of s.villages||[]){const v=w.villages.find(x=>x.id===r.id);if(!v)continue;ensureNation29(v,w);const idx=ensureLaborIndex29(v,w),vw=(v.residents||[]).reduce((a,p)=>a+Number(p.gold29||0),0),vm=[...v.territory].reduce((a,id)=>a+Number(w.map.get(id)?.v29Economy?.marketGold||0),0),un=(v.residents||[]).filter(p=>p.alive&&p.age>=15&&p.assignment!=='PIONEER'&&p.job==='무직').length,cap=idx.slots.reduce((a,x)=>a+x.cap,0),use=idx.slots.reduce((a,x)=>a+x.used,0),st=v.v29Stats;Object.assign(r,{personGold29:+vw.toFixed(2),settlementMarketGold29:+vm.toFixed(2),domesticTrades29:st.domesticTrades,domesticTradeVolume29:+st.domesticTradeVolume.toFixed(2),domesticTradeGold29:+st.domesticTradeGold.toFixed(2),wages29:+st.wages.toFixed(2),consumption29:+st.consumption.toFixed(2),taxes29:+st.taxes.toFixed(2),publicSpending29:+st.publicSpending.toFixed(2),unemployed29:un,jobCapacity29:cap,jobUsed29:use});wallet+=vw;market+=vm;trades+=st.domesticTrades;vol+=st.domesticTradeVolume;gold+=st.domesticTradeGold;wages+=st.wages;cons+=st.consumption;tax+=st.taxes;pub+=st.publicSpending;unemployed+=un;capacity+=cap;used+=use;}Object.assign(s.global,{personGold29:+wallet.toFixed(2),settlementMarketGold29:+market.toFixed(2),domesticTrades29:trades,domesticTradeVolume29:+vol.toFixed(2),domesticTradeGold29:+gold.toFixed(2),wages29:+wages.toFixed(2),consumption29:+cons.toFixed(2),taxes29:+tax.toFixed(2),publicSpending29:+pub.toFixed(2),unemployed29:unemployed,jobCapacity29:capacity,jobUsed29:used,v29SettlementCacheMs:+Number(w._v29Perf?.settlementCacheMs||0).toFixed(2),v29LaborIndexMs:+Number(w._v29Perf?.laborIndexMs||0).toFixed(2),v29JobSearchMs:+Number(w._v29Perf?.jobSearchMs||0).toFixed(2),v29DomesticEconomyMs:+Number(w._v29Perf?.domesticEconomyMs||0).toFixed(2),v29MigrationEvalMs:+Number(w._v29Perf?.migrationEvalMs||0).toFixed(2),v29RouteLookupMs:+Number(w._v29Perf?.routeLookupMs||0).toFixed(2)});w._v29Perf={};return s;};
NS.Telemetry.prototype.snapshotsCSV=function(){const extra=['personGold29','settlementMarketGold29','domesticTrades29','domesticTradeVolume29','domesticTradeGold29','wages29','consumption29','taxes29','publicSpending29','unemployed29','jobCapacity29','jobUsed29'],base=csv28.call(this),lines=base.split('\n');if(!lines.length)return base;const esc=v=>`"${String(v??'').replace(/"/g,'""')}"`;lines[0]+=','+extra.map(esc).join(',');let i=1;for(const s of this.snapshots||[])for(const v of s.villages||[]){if(i>=lines.length)break;lines[i++]+=','+extra.map(k=>esc(v[k]??s.global?.[k])).join(',');}return lines.join('\n');};
NS.Telemetry.prototype.toJSON=function(w){const d=json28.call(this,w);d.version='0.29';Object.assign(d.worldSummary,{v29Revision:REV29,foodConsumption:'0-14: 0.30 / cycle; 15+: 0.42 / cycle',highTierMaterials:'initial/T1 unchanged; high-tier wood x2.0, stone x1.2, Gold unchanged',jobCapacity:'facility-based finite job slots with technology-driven capacity growth',domesticEconomy:'Person wages -> consumption -> settlement market cash -> taxes -> Nation treasury -> targeted public spending',domesticTrade:'settlement price/demand/logistics-based physical internal trade with settlement commercial Gold transfer',settlementEconomy:'local demand, prices, commercial cash, hub score and emergent role',optimization:'cached settlement context + cached labor/vacancy index + slower structural decisions + shared route cache',migration:'P1 reverse penalty retained; longer settlement inertia and small conserved moving cost',lifeZoneMap:'V0.28 P1 hub-anchored life zones visualized as a map layer; non-administrative'});return d;};

