function attachV29World(w){NS.V028.attachWorld(w);for(const v of w.villages||[]){ensureNation29(v,w);for(const p of v.specializationProjects||[])p._v29CostMetadata=p._v29CostMetadata||false;v._v29LaborIndex=null;v._v29SettlementCache=null;}w.v29=w.v29||{revision:REV29};return w;}
