NS.World.prototype.serialize=function(){const d=ser28.call(this);d.version='0.29';d.v29={revision:REV29,foodNeed:FOOD_NEED29,highTierWoodMultiplier:2,highTierStoneMultiplier:1.2,domesticGold:true,finiteJobSlots:true,settlementEconomy:true,lifeZoneMap:true,optimization:true};d.v29Nations=(this.villages||[]).map(v=>({id:v.id,stats:{...ensureNation29(v,this).v29Stats}}));return d;};
NS.World.from=function(d){if(d?.version==='0.29'){const w=from28({...d,version:'0.28'});attachV29World(w);for(const x of d.v29Nations||[]){const v=w.villages.find(q=>q.id===x.id);if(v)v.v29Stats={...ensureNation29(v,w).v29Stats,...(x.stats||{})};}return w;}return attachV29World(from28(d));};
