if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.29'))NS.PATCH_NOTES.unshift({version:'V0.29',date:'2026-09-24',title:'국내경제권·Gold 순환 V2',summary:'Person의 노동·소득·소비와 Settlement별 가격·물류·상업자금을 연결하고, 생산시설의 실제 근무 한계와 후기 자재수요를 도입했습니다.',sections:[['경제',['Person 임금→소비→지역 상업자금→세금→국가재정→공공지출의 국내 Gold 순환을 추가했습니다.','Settlement별 수요·가격·물류비와 상업 중심성이 국내 자원거래를 만들며 생산지·주거지·상업중심지가 자연스럽게 분화합니다.','국가간 교역과 외교·전략적 억제는 기존처럼 유지됩니다.']],['생산·밸런스',['식량 소모: 0~14세 0.30, 15세 이상 0.42 / 경제 사이클.','농경지·채석장·시장·교역소·학당 등에 실제 근무 슬롯을 두고 기술이 일부 시설의 최대 고용량을 늘립니다.','초기/T1 건설비는 유지하고 고티어 건설·개축의 목재는 ×2.0, 석재는 ×1.2로 조정합니다.']],['UI·관측',['Settlement 상세 화면을 압축하고 보유 건물별 상태·주거수용·실제 근무자/최대 슬롯·저장기여를 펼쳐 볼 수 있습니다.','지도에 생활권 레이어를 추가해 P1 hub-anchored 생활권의 중심지·구성 Settlement·근접 영향권을 색으로 표시합니다.']],['성능',['직업 검색은 Settlement 노동/vacancy 인덱스를 공유하고 안정된 Person은 무거운 재평가를 건너뜁니다.','Settlement 공통 평가와 경로비를 캐시하고 경제 계산은 월 단위 pulse로 분리했습니다.','이주 판단의 정착 관성을 더 늘리고 V0.29 전용 성능·경제 telemetry를 추가했습니다.']]]});

(function(){const KEY='village-observer-v0-29',fallback=['village-observer-v0-28','village-observer-v0-27','village-observer-v0-26','village-observer-v0-25','village-observer-v0-24','village-observer-v0-23','village-observer-v0-22','village-observer-v0-21','village-observer-v0-20','village-observer-v0-19','village-observer-v0-18','village-observer-v0-17','village-observer-v0-16','village-observer-v0-15','village-observer-v0-14','village-observer-v0-13','village-observer-v0-12','village-observer-v0-11','village-observer-v0-10','village-observer-v0-9','village-observer-v0-8'];function dl(name,text,type='application/json'){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}NS.SaveSystem={save(w){localStorage.setItem(KEY,JSON.stringify(w.serialize()));},load(){let r=localStorage.getItem(KEY);for(const k of fallback)if(!r)r=localStorage.getItem(k);return r?NS.World.from(JSON.parse(r)):null;},export(w){dl(`village-observer-v029-save-${w.year}y.json`,JSON.stringify(w.serialize()));},exportDevJSON(w){dl(`village-observer-v029-devlog-${w.telemetry.sessionId}.json`,JSON.stringify(w.telemetry.toJSON(w)));},exportDevCSV(w){dl(`village-observer-v029-snapshots-${w.telemetry.sessionId}.csv`,'\ufeff'+w.telemetry.snapshotsCSV(),'text/csv;charset=utf-8');},async import(file){return NS.World.from(JSON.parse(await file.text()));},async importMap(file){return attachV29World(NS.V019.worldFromMapData(JSON.parse(await file.text())));}};})();

